  `id` int NOT NULL AUTO_INCREMENT COMMENT '线索ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '线索名称',
  `source` tinyint NOT NULL COMMENT '线索来源',
  `mobile` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '联系电话',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定电话',
  `email` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `level` tinyint DEFAULT NULL COMMENT '线索等级',
  `industry` tinyint DEFAULT NULL COMMENT '所属行业',
  `addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '备注信息',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `owner_user_id` int DEFAULT NULL COMMENT '线索负责人',
  `owner_time` int DEFAULT '0' COMMENT '领取或分配时间',
  `create_user_id` int NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `gps` varchar(28) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'GPS坐标',
  `is_transform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否转换（0未转换，1已转换）',
  `last_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '最后跟进记录',
  `last_time` int DEFAULT '0' COMMENT '最后跟进时间',
  `next_time` int DEFAULT NULL COMMENT '下次跟进时间',
  `last_user_id` int DEFAULT NULL COMMENT '最后跟进人',
  `customer_id` int DEFAULT NULL COMMENT '已转换的客户id',
  `contact_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `wechat` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人微信',
  `keywords` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '推广关键词',
  `company_id` int DEFAULT NULL COMMENT '对接主体id',
  `cust_status` tinyint DEFAULT NULL COMMENT '客户状态',
  `labels` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '意向标签',
  `clue_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '线索类型:1=公海线索,2=我的线索,3=垃圾线索,4=高企名单',
  `trash_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '丢弃原因',
  `trash_user_id` int DEFAULT '0' COMMENT '丢弃人',
  `trash_time` int DEFAULT '0' COMMENT '丢弃时间',
  `allocation_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '转让原因',
  `customer_level` tinyint NOT NULL DEFAULT '0' COMMENT '客户类型',
  `customer_budget` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户预算',
  `optimizer_user_id` int DEFAULT NULL COMMENT '优化师ID',
  `init_info` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '初始信息及需求',
  `sales_group_build` tinyint(1) NOT NULL DEFAULT '2' COMMENT '售前群是否建立:1=建立,2=未建立',
  `sales_group_info` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '售前群名称',
  `prototype_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '原型图链接',
  `assistant_user_id` int DEFAULT '0' COMMENT '协助人ID',
  `customer_cac` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客资成本',
  `weike_id` varchar(30) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '威客id',
  `weike_no` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '威客任务编号',
  `mark_red` tinyint DEFAULT '1' COMMENT '标红：1=否，2=标红',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `create_user_id` (`create_user_id`) USING BTREE,
  KEY `level` (`level`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5944 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='销售线索信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

