--
-- Table structure for table `speed_clues_quotation`
--

DROP TABLE IF EXISTS `speed_clues_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `speed_clues_quotation` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `clues_id` bigint unsigned NOT NULL COMMENT '线索ID',
  `quotation_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '报价编号',
  `quotation_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '报价名称',
  `version_no` int unsigned NOT NULL DEFAULT '1' COMMENT '线索内报价版本号',
  `is_latest` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '是否最新报价 0-否 1-是',
  `quote_status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '报价状态 0-未报价 1-已报价',
  `approval_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '审批状态 0-未提交审批 1-总经理审批中 2-已审核 3-已驳回',
  `quote_amount` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT '报价总额',
  `quote_user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '报价人ID',
  `quote_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '报价人姓名',
  `estimate_period` int unsigned NOT NULL DEFAULT '0' COMMENT '预计周期/天',
  `evaluator_ids` json DEFAULT NULL COMMENT '技术评估人ID数组',
  `evaluator_names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '技术评估人姓名，多个用顿号分隔',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '报价说明',
  `system_config` json NOT NULL COMMENT '报价系统配置快照',
  `summary_data` json NOT NULL COMMENT '报价汇总结果快照',
  `summary_image_ca_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '报价汇总图 线索资料ID',
  `quotation_ca_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '报价单 线索资料ID',
  `tad_ca_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '技术评估文件 线索资料ID',
  `created_user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `created_user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人姓名',
  `created_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建IP',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_clues_latest` (`clues_id`,`is_latest`) USING BTREE,
  KEY `idx_clues_create` (`clues_id`,`create_time`) USING BTREE,
