DROP TABLE IF EXISTS `speed_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `speed_customer` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '客户ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客户名称',
  `mobile` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机号码',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话号码',
  `email` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `source` tinyint DEFAULT NULL COMMENT '客户来源',
  `customer_level` tinyint DEFAULT NULL COMMENT '客户等级',
  `industry` tinyint DEFAULT NULL COMMENT '所属行业',
  `addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客户地址',
  `gps` varchar(28) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'GPS坐标',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注信息',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_user_id` int NOT NULL DEFAULT '0' COMMENT '创建人ID',
  `owner_user_id` int NOT NULL DEFAULT '0' COMMENT '负责人ID',
  `last_record` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后跟进记录',
  `last_time` int NOT NULL DEFAULT '0' COMMENT '最后跟进时间',
  `last_user_id` int DEFAULT NULL COMMENT '最后跟进人',
  `transfer_count` int NOT NULL DEFAULT '0' COMMENT '转移次数',
  `deal_status` tinyint NOT NULL DEFAULT '0' COMMENT '成交状态(0:未成交 1:已成交 2:已流失)',
  `is_receive` tinyint NOT NULL DEFAULT '0' COMMENT '是否分配(0:否 1:是)',
  `receive_time` int NOT NULL DEFAULT '0' COMMENT '分配时间/领取时间',
  `deal_time` int DEFAULT NULL COMMENT '成交时间',
  `next_time` int DEFAULT NULL COMMENT '下次联系时间',
  `customer_type` tinyint(1) DEFAULT NULL COMMENT '客户类型',
  `company_size` tinyint(1) DEFAULT NULL COMMENT '企业规模',
  `main_contact` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主要联系人',
  `reg_capital` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '注册资本',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `create_user_id` (`create_user_id`) USING BTREE COMMENT '创建人索引',
  KEY `respon_user_id` (`owner_user_id`) USING BTREE COMMENT '负责人索引'
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='客户信息主表';
/*!40101 SET character_set_client = @saved_cs_client */;

