/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `speed_knowledge` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文档名称',
  `file_id` int NOT NULL DEFAULT '0' COMMENT '关联文件ID',
  `dept_id` int NOT NULL DEFAULT '0' COMMENT '归属部门ID',
  `category` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文档分类',
  `view_scope` tinyint(1) NOT NULL DEFAULT '1' COMMENT '查看权限 1内部公开 2所有人可查看',
  `description` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '文档说明',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `create_user_id` int NOT NULL DEFAULT '0' COMMENT '上传人ID',
  `update_user_id` int NOT NULL DEFAULT '0' COMMENT '更新人ID',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 1正常 2停用',
  PRIMARY KEY (`id`),
  KEY `idx_dept_id` (`dept_id`),
  KEY `idx_category` (`category`),
  KEY `idx_view_scope` (`view_scope`),
  KEY `idx_create_user_id` (`create_user_id`),
  KEY `idx_status_delete_time` (`status`,`delete_time`),
  KEY `idx_dept_scope_status` (`dept_id`,`view_scope`,`status`,`delete_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='知识库文档表';
