--
-- Table structure for table `speed_my_company`
--

DROP TABLE IF EXISTS `speed_my_company`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `speed_my_company` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公司全称',
  `company_short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公司简称',
  `credit_code` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统一社会信用代码',
  `legal_person` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '法定代表人',
  `registered_capital` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '注册资本（如：1000万元）',
  `register_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '注册地址',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '联系电话',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '联系邮箱',
  `postal_code` varchar(20) NOT NULL DEFAULT '' COMMENT '邮政编码',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态:1=启用,2=禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `invoice_title` varchar(100) DEFAULT NULL COMMENT '开票抬头',
  `taxpayer_no` varchar(100) DEFAULT NULL COMMENT '纳税人识别号',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '银行账号',
  `invoice_address` varchar(200) DEFAULT NULL COMMENT '开票地址',
  `invoice_phone` varchar(50) DEFAULT NULL COMMENT '开票电话',
  `branch_code` varchar(100) DEFAULT NULL COMMENT '行号',
  `website` varchar(100) DEFAULT NULL COMMENT '官网',
  `contract_no_prefix` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '合同编号前缀',
  `contract_no_seq_reset_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '合同编号流水重置方式:1=按天,2=按月,3=按年,4=永不重置',
  `contract_no_seq_length` tinyint unsigned NOT NULL DEFAULT '3' COMMENT '合同编号流水位数',
  `contract_no_status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '合同编号规则状态:1=启用,2=禁用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='公司主体信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

