  `project_id` int DEFAULT '0' COMMENT '项目id',
  `report_id` int NOT NULL COMMENT '日报id',
  `add_date` date NOT NULL COMMENT '汇报日期',
  `cost_hours` decimal(10,1) DEFAULT NULL COMMENT '耗时',
  `work_info` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '工作内容',
  `work_risk` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT ' 风险/异常反馈',
  `job_attributes` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '工作属性',
  `create_time` int DEFAULT NULL COMMENT '创建时间',
  `detail_type` tinyint(1) DEFAULT '1' COMMENT '详情类型：1=交付部门日报,2=新媒体日报,3=销售部门日报',
  `media_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '新媒体-账号',
  `consume_amount` decimal(10,2) DEFAULT '0.00' COMMENT '新媒体-消耗金额',
  `total_customers` int DEFAULT '0' COMMENT '新媒体-总客资数',
  `valid_customers` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '新媒体-有效客资数',
  `customer_cost` decimal(10,2) DEFAULT '0.00' COMMENT '新媒体-客资成本',
  `valid_rate` decimal(10,2) DEFAULT '0.00' COMMENT '新媒体-有效率',
  `source` int DEFAULT NULL COMMENT '新媒体-渠道',
  `media_project_id` tinyint DEFAULT NULL COMMENT '新媒体-项目ID',
  `clues_id` int DEFAULT '0' COMMENT '销售部门-线索ID',
  `sales_type` tinyint(1) DEFAULT '1' COMMENT '销售部门-类型：1 线索，2 项目',
  `belong_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '统一日报工作归属类型',
  `business_type_id` int unsigned DEFAULT '0' COMMENT '日报配置一级分类ID',
  `report_project_config_id` int unsigned DEFAULT '0' COMMENT '日报配置二级项目ID',
  `belong_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '工作归属名称快照',
  PRIMARY KEY (`id`),
  KEY `idx_belong_type` (`belong_type`),
  KEY `idx_business_type_id` (`business_type_id`),
  KEY `idx_report_project_config_id` (`report_project_config_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3918 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='项目日报关联';
