  `amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `remark` varchar(1000) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `effective_time` int NOT NULL DEFAULT '0' COMMENT '生效时间',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态 1正常 2禁用',
