  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_cost_type` (`cost_type`),
  KEY `idx_effective_time` (`effective_time`),
  KEY `idx_status_delete_time` (`status`,`delete_time`),
  KEY `idx_cost_type_effective_time` (`cost_type`,`effective_time`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='人资费用表';
