--
-- Table structure for table `speed_user_hour_snapshot`
--

DROP TABLE IF EXISTS `speed_user_hour_snapshot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `speed_user_hour_snapshot` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `share_year` smallint unsigned NOT NULL DEFAULT '0' COMMENT '分摊年份',
  `share_month` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '分摊月份',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `username` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名快照',
  `realname` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '姓名快照',
  `dept_id` int unsigned NOT NULL DEFAULT '0' COMMENT '部门ID快照',
  `position_id` int unsigned NOT NULL DEFAULT '0' COMMENT '职位ID快照',
  `jobname` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '职位名称快照',
  `job_status` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '在职状态快照',
  `salary_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '薪资类型 probation试用期 regular转正 adjusted调薪后',
  `salary_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '本次采用的工资金额',
  `social_security_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '社保金额快照',
  `housing_fund_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '公积金金额快照',
  `salary_cost_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '工资口径成本金额，用于除工天前的分子',
  `salary_effective_date` int NOT NULL DEFAULT '0' COMMENT '本次采用口径对应的生效日期',
  `workday_num` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '工天数',
  `daily_hour_num` tinyint unsigned NOT NULL DEFAULT '8' COMMENT '每日工时',
  `hour_share_amount` decimal(14,6) NOT NULL DEFAULT '0.000000' COMMENT '小时公摊金额',
  `user_hour_amount` decimal(14,6) NOT NULL DEFAULT '0.000000' COMMENT '员工时薪',
  `share_snapshot_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联小时公摊快照ID',
  `calc_cutoff_time` int NOT NULL DEFAULT '0' COMMENT '计算截止时间',
  `formula_version` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'v1' COMMENT '公式版本',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态 1正常 2禁用',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_year_month_user_delete` (`share_year`,`share_month`,`user_id`,`delete_time`),
  KEY `idx_share_snapshot_id` (`share_snapshot_id`),
  KEY `idx_salary_type` (`salary_type`),
  KEY `idx_status_delete_time` (`status`,`delete_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='员工月时薪快照表';
/*!40101 SET character_set_client = @saved_cs_client */;

