CREATE TABLE `speed_workday` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `work_year` smallint unsigned NOT NULL DEFAULT '0' COMMENT '年份',
  `work_month` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '月份',
  `workday_num` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '工作天数',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态 1正常 2禁用',
  `create_time` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int NOT NULL DEFAULT '0' COMMENT '更新时间',
  `delete_time` int NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_year_month_delete` (`work_year`,`work_month`,`delete_time`),
  KEY `idx_work_year` (`work_year`),
  KEY `idx_work_month` (`work_month`),
  KEY `idx_status_delete_time` (`status`,`delete_time`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='工天配置表';
